// lib/models/answer_history.dart
import 'dart:convert';
import 'package:shared_preferences/shared_preferences.dart';

/// 解答履歴 1件分（スナップショット保存型）
/// Phase0/1/2 の拡張に対応：
/// - 可変択数 `choiceCount`
/// - 設問タイプ `questionKind` ('single' / 'multiple' / 'select_incorrect')
/// - 複数解答 `userAnswers` / 複数正答 `correctAnswers`
/// 後方互換：旧データ（単一解答）も自動で配列化して読み込みます。
class AnswerRecord {
  final String id;                // 例: epoch_ms 文字列
  final DateTime ts;              // タイムスタンプ
  final String difficulty;        // '必修問題' / '一般問題' / '状況設定問題'
  final String? domain;           // 分野
  final String? major;            // 大項目
  final String? mid;              // 中項目
  final String? topic;            // 小項目（内部選定）

  // スナップショット（本文）
  final String question;
  final Map<String, String> choices;     // 'A'.. : '本文'
  final String? explanation;             // 解説
  final Map<String, String>? rationales; // 可能なら

  // --- Phase 拡張 ---
  final int choiceCount;                 // 4/5...（未指定時は choices.length を採用）
  final String questionKind;             // 'single' / 'multiple' / 'select_incorrect'
  final List<String> userAnswers;        // ユーザー選択（複数対応）
  final List<String> correctAnswers;     // 正答（複数対応）

  // --- 互換getter（旧UI用） ---
  String? get userAnswer => userAnswers.isNotEmpty ? userAnswers.first : null;
  String  get correct    => correctAnswers.isNotEmpty ? correctAnswers.first : '';

  /// 正誤判定
  /// - multiple: 完全一致（順不同）
  /// - select_incorrect: 正解集合（=誤り集合）とユーザー選択が1つでも重なれば正解
  /// - single: 完全一致
  bool get isCorrect {
    final ua = userAnswers.toSet();
    final ca = correctAnswers.toSet();

    if (ua.isEmpty || ca.isEmpty) return false;

    switch (questionKind) {
      case 'multiple':
      // 複数正答 → 完全一致
        return ua.length == ca.length && ua.containsAll(ca);
      case 'select_incorrect':
      // 誤答選択 → 誤り（=正解集合）から1つでも選べていれば正解
        return ua.intersection(ca).isNotEmpty;
      default:
      // single（その他）→ 完全一致
        return ua.length == ca.length && ua.containsAll(ca);
    }
  }

  const AnswerRecord({
    required this.id,
    required this.ts,
    required this.difficulty,
    required this.domain,
    required this.major,
    required this.mid,
    required this.topic,
    required this.question,
    required this.choices,
    required this.explanation,
    required this.rationales,
    this.choiceCount = 4,
    this.questionKind = 'single',
    List<String>? userAnswers,
    List<String>? correctAnswers,
  })  : userAnswers = userAnswers ?? const <String>[],
        correctAnswers = correctAnswers ?? const <String>[];

  /// 後方互換を考慮した読み込み
  factory AnswerRecord.fromJson(Map<String, dynamic> j) {
    final version = (j['schemaVersion'] as int?) ?? 1;

    // 共通部の取り出し（壊れ値に強く）
    DateTime _parseTs(dynamic v) {
      if (v is int) return DateTime.fromMillisecondsSinceEpoch(v);
      if (v is String) {
        final p = DateTime.tryParse(v);
        if (p != null) return p;
        final asInt = int.tryParse(v);
        if (asInt != null) return DateTime.fromMillisecondsSinceEpoch(asInt);
      }
      return DateTime.now();
    }

    Map<String, String> _parseChoices(dynamic m) {
      if (m is Map) {
        return m.map((k, v) => MapEntry(k.toString(), v.toString()));
      }
      return const <String, String>{};
    }

    final id          = (j['id'] ?? '').toString();
    final ts          = _parseTs(j['ts']);
    final difficulty  = (j['difficulty'] ?? '').toString();
    final domain      = j['domain']?.toString();
    final major       = j['major']?.toString();
    final mid         = j['mid']?.toString();
    final topic       = j['topic']?.toString();
    final question    = (j['question'] ?? '').toString();
    final choices     = _parseChoices(j['choices']);
    final explanation = j['explanation']?.toString();
    final rationales  = (j['rationales'] is Map)
        ? (j['rationales'] as Map).map((k, v) => MapEntry(k.toString(), v.toString()))
        : null;

    // ラベル正規化（' a ' → 'A'）
    List<String> _normList(dynamic any) {
      if (any is List) {
        final set = <String>{};
        for (final e in any) {
          final s = e?.toString().trim().toUpperCase() ?? '';
          if (s.isNotEmpty) set.add(s);
        }
        final out = set.toList()..sort();
        return out;
      }
      return const <String>[];
    }

    // choiceCount の妥当化（未指定は choices.length、最低2）
    int _resolveChoiceCount(int? raw) {
      final fromChoices = choices.length;
      final n = raw ?? fromChoices;
      return n.clamp(2, 26);
    }

    if (version >= 2) {
      final cc   = _resolveChoiceCount(j['choiceCount'] as int?);
      final kind = (j['questionKind'] ?? 'single').toString();
      final ua   = _normList(j['userAnswers']);
      final ca   = _normList(j['correctAnswers']);
      return AnswerRecord(
        id: id,
        ts: ts,
        difficulty: difficulty,
        domain: domain,
        major: major,
        mid: mid,
        topic: topic,
        question: question,
        choices: choices,
        explanation: explanation,
        rationales: rationales,
        choiceCount: cc,
        questionKind: kind,
        userAnswers: ua,
        correctAnswers: ca,
      );
    } else {
      // 旧形式 → 新形式に変換
      final ua = j['userAnswer']?.toString();
      final ca = j['correct']?.toString();

      final uaList = <String>[];
      final caList = <String>[];
      if (ua != null && ua.trim().isNotEmpty) {
        uaList.add(ua.trim().toUpperCase());
      }
      if (ca != null && ca.trim().isNotEmpty) {
        caList.add(ca.trim().toUpperCase());
      }

      return AnswerRecord(
        id: id,
        ts: ts,
        difficulty: difficulty,
        domain: domain,
        major: major,
        mid: mid,
        topic: topic,
        question: question,
        choices: choices,
        explanation: explanation,
        rationales: rationales,
        choiceCount: _resolveChoiceCount(4),
        questionKind: 'single',
        userAnswers: uaList,
        correctAnswers: caList,
      );
    }
  }

  Map<String, dynamic> toJson() => {
    'schemaVersion': 2,
    'id': id,
    'ts': ts.millisecondsSinceEpoch,
    'difficulty': difficulty,
    'domain': domain,
    'major': major,
    'mid': mid,
    'topic': topic,
    'question': question,
    'choices': choices,
    'explanation': explanation,
    'rationales': rationales,
    'choiceCount': choiceCount,
    'questionKind': questionKind,
    'userAnswers': userAnswers,
    'correctAnswers': correctAnswers,
  };

  /// 便利: 一部差し替え
  AnswerRecord copyWith({
    String? id,
    DateTime? ts,
    String? difficulty,
    String? domain,
    String? major,
    String? mid,
    String? topic,
    String? question,
    Map<String, String>? choices,
    String? explanation,
    Map<String, String>? rationales,
    int? choiceCount,
    String? questionKind,
    List<String>? userAnswers,
    List<String>? correctAnswers,
  }) {
    return AnswerRecord(
      id: id ?? this.id,
      ts: ts ?? this.ts,
      difficulty: difficulty ?? this.difficulty,
      domain: domain ?? this.domain,
      major: major ?? this.major,
      mid: mid ?? this.mid,
      topic: topic ?? this.topic,
      question: question ?? this.question,
      choices: choices ?? this.choices,
      explanation: explanation ?? this.explanation,
      rationales: rationales ?? this.rationales,
      choiceCount: choiceCount ?? this.choiceCount,
      questionKind: questionKind ?? this.questionKind,
      userAnswers: userAnswers ?? this.userAnswers,
      correctAnswers: correctAnswers ?? this.correctAnswers,
    );
  }
}

/// 履歴の保存・取得（SharedPreferences, List<String>）
/// - ストレージキー: 'answer_history_v3'
/// - 1件=1JSON文字列 で先頭挿入（最新が先頭）
/// - 破損エントリはスキップして読み込む
class AnswerHistory {
  AnswerHistory._();
  static final AnswerHistory instance = AnswerHistory._();

  static const _storageKey = 'answer_history_v3';
  static const _maxKeep = 500;

  Future<List<AnswerRecord>> all() async {
    final sp = await SharedPreferences.getInstance();
    final raw = sp.getStringList(_storageKey) ?? const <String>[];

    final out = <AnswerRecord>[];
    for (final s in raw) {
      try {
        final obj = jsonDecode(s);
        if (obj is Map<String, dynamic>) {
          out.add(AnswerRecord.fromJson(obj));
        } else if (obj is Map) {
          out.add(AnswerRecord.fromJson(Map<String, dynamic>.from(obj)));
        }
      } catch (_) {
        // 壊れたエントリはスキップ
      }
    }
    return out;
  }

  Future<void> add(AnswerRecord rec) async {
    final sp = await SharedPreferences.getInstance();
    final list = sp.getStringList(_storageKey) ?? <String>[];
    list.insert(0, jsonEncode(rec.toJson()));
    if (list.length > _maxKeep) {
      list.removeRange(_maxKeep, list.length);
    }
    await sp.setStringList(_storageKey, list);
  }

  Future<void> clear() async {
    final sp = await SharedPreferences.getInstance();
    await sp.remove(_storageKey);
  }
}

// lib/models/category_models.dart

/// 分野（Domain）> 大項目（Major）> 中項目（Mid）> トピック（Topic）
/// のツリー構造を型で表現するためのモデル。

class Topic {
  final String id;     // 内部ID（=既存のラベルでもOK）
  final String label;  // 表示名
  const Topic({required this.id, required this.label});
}

class MidCategory {
  final String id;
  final String label;
  final List<Topic> topics;
  const MidCategory({
    required this.id,
    required this.label,
    required this.topics,
  });
}

class MajorCategory {
  final String id;
  final String label;
  final List<MidCategory> mids;
  const MajorCategory({
    required this.id,
    required this.label,
    required this.mids,
  });
}

class DomainCategory {
  final String id;       // 例: '成人看護学' / '必修'
  final String label;    // 表示名
  final List<MajorCategory> majors;
  const DomainCategory({
    required this.id,
    required this.label,
    required this.majors,
  });
}

/// 分野〜トピックを指すパス（履歴保存・選定結果の受け渡しに便利）
class CategoryPath {
  final String domainId;
  final String majorId;
  final String? midId;
  final String? topicId;
  const CategoryPath({
    required this.domainId,
    required this.majorId,
    this.midId,
    this.topicId,
  });

  CategoryPath copyWith({
    String? domainId,
    String? majorId,
    String? midId,
    String? topicId,
  }) {
    return CategoryPath(
      domainId: domainId ?? this.domainId,
      majorId: majorId ?? this.majorId,
      midId: midId ?? this.midId,
      topicId: topicId ?? this.topicId,
    );
  }
}

/// （任意）状況設定の観点コードを型で扱うためのenum
enum ScenarioAspect { A, B, C, D, E }

extension ScenarioAspectX on ScenarioAspect {
  String get code => toString().split('.').last; // 'A'..'E'
  static ScenarioAspect? fromCode(String? c) {
    if (c == null) return null;
    switch (c) {
      case 'A': return ScenarioAspect.A;
      case 'B': return ScenarioAspect.B;
      case 'C': return ScenarioAspect.C;
      case 'D': return ScenarioAspect.D;
      case 'E': return ScenarioAspect.E;
    }
    return null;
  }
}

// lib/models/history_models.dart

/// 1問ぶんの履歴を表すモデル。
/// 既存の保存形式に合わせて Map との相互変換も用意しています。
class HistoryRecord {
  final DateTime timestamp;   // 解答時刻
  final String difficulty;    // '必修問題' / '一般問題' / '状況設定問題'
  final String domain;        // 分野
  final String major;         // 大項目
  final String? mid;          // 中項目（任意）
  final String? topic;        // トピック（任意）
  final bool correct;         // 正解なら true
  final int? elapsedMs;       // 解答に要した時間（ミリ秒／任意）

  const HistoryRecord({
    required this.timestamp,
    required this.difficulty,
    required this.domain,
    required this.major,
    this.mid,
    this.topic,
    required this.correct,
    this.elapsedMs,
  });

  /// Map -> HistoryRecord（ストレージや既存JSONからの復元用）
  factory HistoryRecord.fromMap(Map<String, dynamic> map) {
    final ts = map['timestamp'];
    // ISO8601文字列またはミリ秒UNIXの両対応
    final DateTime t = ts is int
        ? DateTime.fromMillisecondsSinceEpoch(ts)
        : DateTime.tryParse(ts?.toString() ?? '') ?? DateTime.now();

    return HistoryRecord(
      timestamp: t,
      difficulty: (map['difficulty'] ?? '').toString(),
      domain: (map['domain'] ?? '').toString(),
      major: (map['major'] ?? '').toString(),
      mid: map['mid']?.toString(),
      topic: map['topic']?.toString(),
      correct: (map['correct'] == true) || (map['isCorrect'] == true),
      elapsedMs: map['elapsedMs'] is int ? map['elapsedMs'] as int : null,
    );
  }

  /// HistoryRecord -> Map（保存・共有用）
  Map<String, dynamic> toMap() {
    return {
      'timestamp': timestamp.toIso8601String(),
      'difficulty': difficulty,
      'domain': domain,
      'major': major,
      if (mid != null) 'mid': mid,
      if (topic != null) 'topic': topic,
      'correct': correct,
      if (elapsedMs != null) 'elapsedMs': elapsedMs,
    };
  }
}

/// 日別要約（チャートに載せやすい形）
class DailySummary {
  final DateTime date; // 時刻は 00:00 固定
  final int total;
  final int correct;
  double get accuracy => total == 0 ? 0 : correct / total;

  const DailySummary({
    required this.date,
    required this.total,
    required this.correct,
  });
}

/// ドメイン別要約
class DomainSummary {
  final String domain;
  final int total;
  final int correct;
  double get accuracy => total == 0 ? 0 : correct / total;

  const DomainSummary({
    required this.domain,
    required this.total,
    required this.correct,
  });
}

/// ローリング（移動平均）精度の一点
class RollingPoint {
  final DateTime date;
  final double accuracy; // 0..1
  const RollingPoint({required this.date, required this.accuracy});
}

/// 連続正解/不正解の情報
class Streaks {
  final int currentCorrect; // 直近の連続正解数
  final int bestCorrect;    // 過去最大の連続正解数
  final int currentWrong;   // 直近の連続不正解数
  final int bestWrong;      // 過去最大の連続不正解数

  const Streaks({
    required this.currentCorrect,
    required this.bestCorrect,
    required this.currentWrong,
    required this.bestWrong,
  });
}
